import re

with open("app/src/main/java/com/example/data/WorshipData.kt", "r", encoding="utf-8") as f:
    content = f.read()

target = """اللّهُمَّ سَمِعْنا لأمْرِكَ وَأَطَعْنا وَاتَّبَعْنا صِراطَكَ المُسْتَقِيمَ فَاهْدِنا رَبَّنا وَلا تُزِغْ قُلُوبَنا بَعْدَ إِذْ هَدَيْتَنا إِلى طاعَتِكَ وَاجْعَلْنا مِنَ الشَّاكِرِينَ لأَنْعُمِكَ، وَأَشْهَدُ أَنَّكَ لَمْ تَزَلْ لِلْهَوى مُخالِفاً وَلِلْتُقى مُحالِفاً وَعَلى كَظْمِ الغَيْظِ قادِراً وَعَنِ النَّاسِ عافِياً غافِراً وَإِذا عُصيَ الله ساخِطاً وَإِذا اُطِيعَ الله راضِياً وَبِما عَهِدَ إِلَيْكَ عامِلاً راعِياً لِما اسْتُحْفِظْتَ حافِظاً لِما اسْتُوْدِعْتَ مُبَلِّغاً ما حُمِّلْتَ مُنْتَظِراً ما وُعِدْتَ، وَأَشْهَدُ أَنَّكَ ما الدَّعَيْتَ وَلا الجَحَدْتَ وَلا اسْتَعْتَبْتَ وَلا أَذْعَنْتَ وَلا نَكَصْتَ وَلا ارْتَدَدْتَ، بَلْ حافَظْتَ عَلى عَهْدِكَ وَوَصِيَّتِكَ وَلَمْ تَتَنافَسْ فِي المُشْتَبِهاتِ مِنْ الدُّنْيا وَلَمْ تَحْزَنْ عَلى ما زُوِيَ عَنْكَ مِنْها، وَبِئْسَ القَوْمُ الَّذِينَ جاهَدُوكَ وَحارَبُوكَ وَنابَذُوكَ وَناصَبُوكَ، فَكَيْفَ أَنْتَ يا أَمِيرَ المُؤْمِنِينَ وَعَلَيْكَ السَّلامُ وَرَحْمَةُ الله وَبَرَكاتُهُ.*المصدر:مفاتيح الجنان.\"\"\"),"""

replacement = """اللّهُمَّ سَمِعْنا لأمْرِكَ وَأَطَعْنا وَاتَّبَعْنا صِراطَكَ المُسْتَقِيمَ فَاهْدِنا رَبَّنا وَلا تُزِغْ قُلُوبَنا بَعْدَ إِذْ هَدَيْتَنا إِلى طاعَتِكَ وَاجْعَلْنا مِنَ الشَّاكِرِينَ لأَنْعُمِكَ، وَأَشْهَدُ أَنَّكَ لَمْ تَزَلْ لِلْهَوى مُخالِفاً وَلِلْتُقى مُحالِفاً وَعَلى كَظْمِ الغَيْظِ قادِراً وَعَنِ النَّاسِ عافِياً غافِراً وَإِذا عُصيَ الله ساخِطاً وَإِذا اُطِيعَ الله راضِياً وَبِما عَهِدَ\"\"\"),"""

if target in content:
    content = content.replace(target, replacement)
    with open("app/src/main/java/com/example/data/WorshipData.kt", "w", encoding="utf-8") as f:
        f.write(content)
    print("SUCCESS")
else:
    print("TARGET NOT FOUND")
